func ActionByID(id string) (Action, bool) {
	if d, ok := DirectionByID(id); ok {
		return directionAction(d), true
	}
	for _, a := range Actions {
		if a.ID == id {
			return a, true
		}
	}
	return Action{}, false
}
func Categories() []string {
	var out []string
	for _, a := range Actions {
		found := false
		for _, s := range out {
			found = found || s == a.Category
		}
		if !found {
			out = append(out, a.Category)
		}
	}
	return out
}
